"""Original toxicology: cardiac drugs, acetaminophen and salicylates."""
from create_critical_toxicology_basics import rows,q,AH,IC,AC,AP,ref
NA=ref('ACMT acetylcysteine duration practice statement: 2026','https://www.acmt.net/news/acmt-practice-statement-duration-of-intravenous-acetylcysteine-therapy-following-acetaminophen-overdose-2026-update/')
SA=ref('EXTRIP salicylate recommendations','https://www.extrip-workgroup.org/salicylates')

q('An adult has verapamil overdose with hypotension, bradycardia and hyperglycemia. Which targeted metabolic therapy is recommended as part of treatment for life-threatening hypotension?', 'High-dose insulin with glucose support and close electrolyte monitoring',[
 ('Glucagon alone as a reliable definitive treatment','Its usefulness in CCB poisoning is uncertain and it does not replace the recommended support bundle.'),('A beta blocker to counter reflex sympathetic activation','Further negative chronotropic/inotropic effects can worsen toxicity.'),('Routine hemodialysis to efficiently remove verapamil','Its distribution and protein binding make conventional dialysis ineffective for meaningful removal.')],
 'CCB toxicity impairs both perfusion and substrate utilization','**High-dose insulin can support myocardial performance in severe CCB poisoning.**',['Vasopressors and calcium are additional indicated components according to physiology.','Hyperglycemia can be a clue to pancreatic insulin suppression.'],'**Use a monitored toxicology/ICU protocol.**',['Follow glucose, potassium, perfusion and fluid balance closely.','Refractory cardiovascular collapse may warrant extracorporeal life-support discussion.'],[['Insulin','Metabolic/inotropic support'],['Glucose/potassium','Frequent monitoring'],['Other support','Vasopressors, calcium and selected ECLS']],[AH],style='clinical_scenario')

q('Which beta-blocker overdose is particularly associated with sodium-channel blockade, seizures and QRS widening?', 'Propranolol',[
 ('Atenolol','It is less lipophilic and more renally cleared; it is not the classic sodium-channel/seizure phenotype.'),('Sotalol','Its prominent additional hazard is QT prolongation and torsades.'),('Esmolol','Its short duration differs from the classic severe lipophilic membrane-stabilizing overdose.')],
 'Beta blockers have clinically important differences','**Propranolol combines beta blockade with lipophilicity and sodium-channel effects.**',['Severe poisoning can cause CNS toxicity and conduction delay.','Sotalol adds potassium-channel-related repolarization toxicity.'],'**Treat shock, seizures and conduction toxicity according to mechanism.**',['High-dose insulin and vasopressors may be needed for severe hemodynamic toxicity.','Widened QRS from sodium-channel blockade supports bicarbonate treatment.'],[['Propranolol','CNS toxicity/QRS widening'],['Sotalol','QT prolongation'],['Atenolol','Renal elimination; selected dialysis role']],[AH])

q('A patient with amitriptyline overdose develops hypotension and QRS duration 150 ms. Which specific treatment is most appropriate?', 'Intravenous sodium bicarbonate with ECG, pH and electrolyte reassessment',[
 ('Physostigmine for the associated antimuscarinic delirium','Conduction toxicity makes this an unsafe choice.'),('A class IA antiarrhythmic to narrow the QRS','Additional sodium-channel blockade can worsen cardiotoxicity.'),('Flumazenil to reverse all sedative effects','It does not reverse TCA toxicity and can precipitate seizures in mixed poisoning.')],
 'Treat sodium-channel blockade rather than only the rhythm label','**Sodium loading and alkalinization can improve toxin-related conduction impairment.**',['QRS widening, hypotension and ventricular dysrhythmias identify serious toxicity.','Avoid excessive alkalemia and monitor sodium and potassium.'],'**Support circulation and treat seizures while consulting toxicology.**',['Serial ECGs are more useful than a single drug concentration for immediate cardiotoxicity assessment.','A transient response does not exclude recurrent toxicity.'],[['ECG','Wide QRS'],['Mechanism','Fast sodium-channel blockade'],['Specific treatment','Sodium bicarbonate']],[AH],style='clinical_scenario')

q('Which ECG feature is classically associated with tricyclic antidepressant sodium-channel toxicity?', 'A prominent terminal R wave in aVR',[
 ('Diffuse shortened QT as the defining pattern','TCA poisoning more often prolongs conduction intervals.'),('Isolated PR depression with diffuse concave ST elevation','This suggests pericarditis rather than the characteristic toxic conduction pattern.'),('A delta wave with a persistently short PR interval','This describes pre-excitation, not the typical acute TCA finding.')],
 'Terminal depolarization changes can reveal sodium-channel toxicity','**A rightward terminal QRS vector may create a prominent terminal R in aVR.**',['QRS duration and the full clinical picture matter.','This finding is not specific enough to identify a toxin in isolation.'],'**Assess toxicity dynamically and treat severe conduction effects.**',['Review alternative sodium-channel blockers and coingestants.','Use airway, seizure and hemodynamic support alongside bicarbonate when indicated.'],[['aVR','Terminal R clue'],['QRS','Conduction delay'],['Interpretation','Context-dependent toxicity marker']],[AH])

q('A patient with digoxin toxicity has ventricular dysrhythmia and hemodynamic instability. Which antidote is indicated?', 'Digoxin-specific antibody fragments',[
 ('Hemodialysis as the principal digoxin-removal strategy','Digoxin has a large distribution volume and is poorly removed by conventional dialysis.'),('Adenosine as the definitive toxin-neutralizing treatment','It does not bind digoxin or reverse the systemic poisoning.'),('Calcium-channel blockade to correct the toxic mechanism','This can worsen conduction/hemodynamic problems and does not neutralize digoxin.')],
 'Neutralize the toxin in life-threatening cardiac glycoside poisoning','**Fab fragments bind free digoxin and shift the equilibrium away from tissue effects.**',['Severe dysrhythmias and instability warrant urgent treatment.','Potassium and renal function influence risk and follow-up.'],'**Monitor for potassium shifts and recurrent toxicity.**',['Total digoxin measurements after Fab can be misleading unless the assay distinguishes free drug.','Clinical response is central to post-antidote assessment.'],[['Antidote','Digoxin-specific Fab'],['Dialysis','Poor removal'],['After Fab','Interpret assays cautiously']],[AH],style='clinical_scenario')

q('A patient takes a single acute immediate-release acetaminophen overdose at a reliably known time. Which sample can be used with the standard treatment nomogram?', 'A serum acetaminophen concentration obtained at least 4 hours after ingestion within the nomogram window',[
 ('A concentration drawn 30 minutes after ingestion as the final risk assessment','Absorption may be incomplete and an early low result is not reassuring.'),('A urine acetaminophen screen plotted against time','The nomogram uses a quantitative serum concentration.'),('A concentration plotted against the time of hospital arrival','The x-axis is elapsed time from ingestion, not presentation.')],
 'Time and units determine nomogram meaning','**A timed serum level estimates risk only in an appropriate acute-ingestion context.**',['Treatment lines differ by jurisdiction and protocol.','Modified-release products and delayed absorption may need repeat measurements.'],'**Do not delay acetylcysteine when a potentially toxic ingestion is likely and results would delay treatment beyond the safe early window.**',['Check the level units against the selected nomogram.','Unknown-time and repeated supratherapeutic exposures require a different assessment.'],[['Sample','Serum concentration'],['Time reference','Ingestion'],['Early level','May precede peak']],[AP])

q('An adult has an uncertain-time acetaminophen exposure, elevated aminotransferases and a detectable drug concentration. Which approach is appropriate?', 'Start acetylcysteine and use laboratory/clinical risk assessment rather than force-plotting an unknown time',[
 ('Choose an arbitrary ingestion time to obtain a reassuring nomogram point','This creates false precision and can miss toxicity.'),('Withhold treatment because the level is below the 4-hour line','That line cannot be interpreted without a valid elapsed time.'),('Wait for encephalopathy before giving acetylcysteine','Early treatment can prevent progression and remains useful in established injury.')],
 'The nomogram does not repair an unreliable history','**Unknown-time exposure requires a distinct treatment pathway.**',['A low concentration late after injury can coexist with severe hepatotoxicity.','Assess INR, renal function, glucose and acid-base trajectory as well as enzymes.'],'**Consult toxicology and evaluate for acute liver failure when appropriate.**',['Continue treatment according to clinical and biochemical endpoints.','Investigate coingestants and alternative liver injury causes.'],[['Known acute time','Nomogram may apply'],['Unknown time','Clinical/laboratory pathway'],['Liver injury','Do not wait for coma']],[AP,NA],style='clinical_scenario')

q('At the end of a scheduled IV acetylcysteine course, acetaminophen remains detectable and ALT is rising. What is the appropriate principle?', 'Continue acetylcysteine and reassess until appropriate biochemical and clinical stopping criteria are met',[
 ('Stop solely because the scheduled hours are complete','Persistent drug or evolving injury can require a longer course.'),('Stop if the patient has no abdominal pain','Symptoms do not reliably exclude progressive hepatotoxicity.'),('Replace acetylcysteine with charcoal as the only ongoing therapy','Charcoal does not substitute for ongoing antidotal treatment of established systemic risk.')],
 'Treatment duration is endpoint-based','**A fixed infusion schedule is not a mandatory stopping point.**',['Drug clearance, improving aminotransferases and prognostic markers are relevant.','Delayed absorption or liver injury can prolong the required treatment.'],'**Use the current toxicology stopping criteria and specialist advice.**',['Monitor INR, renal function and other indicators of recovery or deterioration.','Escalate early for liver-failure assessment when indicated.'],[['Scheduled endpoint','Reassessment point'],['Persistent drug/injury','Continue and investigate'],['Stopping','Clinical and biochemical recovery criteria']],[NA],style='clinical_scenario')

q('A patient with salicylate poisoning has tachypnea, PaCO2 20 mmHg, bicarbonate 14 mmol/L and an elevated anion gap. Which combination is characteristic?', 'Respiratory alkalosis plus high-anion-gap metabolic acidosis',[
 ('Pure metabolic alkalosis with hypoventilation','The bicarbonate reduction and hyperventilation are inconsistent.'),('Pure chronic respiratory acidosis','CO2 is low rather than high.'),('Normal-gap metabolic acidosis without a respiratory component','Both the gap and the disproportionate CO2 reduction argue against this.')],
 'Salicylates can drive two acid-base processes','**Respiratory stimulation coexists with metabolic toxicity.**',['A near-normal pH can conceal substantial mixed disturbance.','Acidemia increases the un-ionized fraction and tissue/CNS distribution.'],'**Track serial levels, pH and clinical features.**',['Correct volume and potassium deficits and alkalinize when indicated.','Avoid loss of compensatory ventilation if intubation is unavoidable.'],[['Respiratory','Primary hyperventilation'],['Metabolic','Organic acid accumulation'],['Acidemia','Greater tissue penetration']],[SA],style='clinical_scenario')

q('A patient with salicylate poisoning develops confusion and new hypoxemia despite alkalinization. The concentration is below 100 mg/dL. Which action is appropriate?', 'Arrange urgent hemodialysis assessment based on severe clinical toxicity',[
 ('Exclude dialysis because the concentration is below a single numerical threshold','Neurological toxicity and new oxygen-requiring hypoxemia are independent indications.'),('Wait for the concentration to rise further before escalating','Deterioration requires treatment even with a lower measured level, especially in chronic toxicity.'),('Use urinary acidification to increase excretion','Acidification worsens salicylate reabsorption and tissue distribution.')],
 'Clinical severity can overrule a concentration threshold','**EXTRIP includes neurological and respiratory deterioration among dialysis indications.**',['Renal function, acid-base status and failure of standard treatment also matter.','Chronic exposure may be dangerous at lower levels than acute exposure.'],'**Continue appropriate stabilization and bicarbonate while arranging extracorporeal treatment.**',['Intermittent hemodialysis is preferred when feasible.','Maintain ventilation and avoid peri-intubation acidemia.'],[['Clinical warning','Confusion/hypoxemia'],['Level','Not the sole gate'],['Definitive removal','Hemodialysis']],[SA],style='clinical_scenario')
